import{_ as l,a0 as s,w as p,s as u,ao as o,I as r,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"五種方法檢測你的 Linux 是32位還是64位 | LCTT x X-CMD","titleTemplate":false,"description":"五種方法檢測你的 Linux 是32位還是64位 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"五種方法檢測你的 Linux 是32位還是64位 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"五種方法檢測你的 Linux 是32位還是64位 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/5 Ways To Check If Linux OS is 32 bit or 64 Bit","title":"五種方法檢測你的 Linux 是32位還是64位","tag":"201405","desc":""},"relativePath":"201405/5 Ways To Check If Linux OS is 32 bit or 64 Bit.md","filePath":"[post].md"}'),d={name:"201405/5 Ways To Check If Linux OS is 32 bit or 64 Bit.md"};function m(x,t,b,f,h,_){const a=s("Link");return p(),u("div",null,[t[14]||(t[14]=o('<h1 id="五種方法檢測你的-linux-是32位還是64位" tabindex="-1">五種方法檢測你的 Linux 是32位還是64位 <a class="header-anchor" href="#五種方法檢測你的-linux-是32位還是64位" aria-label="Permalink to “五種方法檢測你的 Linux 是32位還是64位”">​</a></h1><p>有的時候 Linux 新手們在下載軟件的時候十分困惑，因為下載頁面常常同時提供32位和64位版本的軟件。所以弄清楚你的操作系統是32位的還是64位的十分重要，因為你在做很多事情的時候都需要這個信息。在這篇文章裏，我們會討論五種檢測你的Linux系統是32位還是64位的方法。</p><h3 id="檢測你的-linux-是32位還是64位的" tabindex="-1">檢測你的 Linux 是32位還是64位的 <a class="header-anchor" href="#檢測你的-linux-是32位還是64位的" aria-label="Permalink to “檢測你的 Linux 是32位還是64位的”">​</a></h3><p>請注意文中的這些方法是在 Ubuntu 13.10 平台測試.</p><h4 id="_1-執行-uname-a-命令" tabindex="-1">1. 執行‘uname -a’ 命令 <a class="header-anchor" href="#_1-執行-uname-a-命令" aria-label="Permalink to “1. 執行‘uname -a’ 命令”">​</a></h4>',5)),r("p",null,[t[1]||(t[1]=n("最常見的一個測試方法是運行 ",-1)),e(a,{href:"http://mylinuxbook.com/linux-uname-command/"},{default:i(()=>[...t[0]||(t[0]=[n("uname command",-1)])]),_:1}),t[2]||(t[2]=n(" 命令。",-1))]),t[15]||(t[15]=o(`<p>例如，在我的系統裏，它顯示了以下信息：</p><pre><code>$ uname -a
 Linux ubuntu 3.11.0-12-generic #19-Ubuntu SMP Wed Oct 9 16:12:00 UTC 2013 i686 athlon i686 GNU/Linux
</code></pre><p>那個高亮的 <strong>i686</strong> (or 有時候會是i386) 説明操作系統是32位的，但是如果顯示的是 <strong>x86_64</strong>，那就説明這個操作系統是64位的。</p><h4 id="_2-運行-uname-m-命令" tabindex="-1">2.運行 ‘uname -m’ 命令 <a class="header-anchor" href="#_2-運行-uname-m-命令" aria-label="Permalink to “2.運行 ‘uname -m’ 命令”">​</a></h4><p>上面的命令內涵太多了，可以用這個參數直指人心：‘uname -m’ 。</p><p>例如，在我的系統裏，它顯示了以下信息：</p><pre><code>$ uname -m
 i686
</code></pre><p>這説明我的 Ubuntu Linux 系統是32位的，如果輸出顯示的是x86_64，就説明系統是64位的。</p><h4 id="_3-使用-file-命令" tabindex="-1">3.使用 file 命令#### <a class="header-anchor" href="#_3-使用-file-命令" aria-label="Permalink to “3.使用 file 命令####”">​</a></h4><p>儘管這樣做純粹是炫耀技巧，但是仍然不失為一種達到目的的方法。使用這個方法，需要你運行 file 命令並帶上 <strong>/sbin/init</strong> 作為參數。</p><p>舉個例子:</p><pre><code>$ file /sbin/init
 /sbin/init: ELF 32-bit LSB shared object, Intel 80386, version 1 (SYSV), dynamically linked (uses shared libs), for GNU/Linux 2.6.24, BuildID[sha1]=0xc0d86a25a7abb14cad4a65a1f7d03605bcbd41f6, stripped
</code></pre><p>高亮的 <strong>32-bit</strong> 説明這是一個32位的操作系統,如果顯示為 <strong>64-bit</strong> 則説明操作系統是64位的</p><h4 id="_4-使用-arch-命令" tabindex="-1">4. 使用 arch 命令 <a class="header-anchor" href="#_4-使用-arch-命令" aria-label="Permalink to “4. 使用 arch 命令”">​</a></h4><p>另外一個可以選擇的方法是使用 arch 命令，這個命令用於輸出機器的硬件名稱。</p><p>這裏有一個示例:</p><pre><code>$ arch
 i686
</code></pre><p>在這裏你可以看到輸出的是 i686, 這説明這是一個32位操作系統，對於64位的操作系統，輸出的應該是x86_64。</p><h4 id="_5-通過系統設置的方法" tabindex="-1">5. 通過系統設置的方法 <a class="header-anchor" href="#_5-通過系統設置的方法" aria-label="Permalink to “5. 通過系統設置的方法”">​</a></h4><p>如果你使用的是 Ubuntu 12.04 或更高, 你可以很簡單地在** All Settings -&gt; Details**裏查看你的系統結構。</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2014/04/details.png" alt="details"></p><p>這樣你就可以看到系統類型(32-bit)在這裏清晰地顯示出來。</p><p>你還知道別的方法來檢測操作系統是32位還是64位的嗎？在下面回覆與我們分享吧。</p><hr>`,24)),r("p",null,[t[4]||(t[4]=n("via: ",-1)),e(a,{href:"http://mylinuxbook.com/5-ways-to-check-if-linux-is-32-bit-or-64-bit/"},{default:i(()=>[...t[3]||(t[3]=[n("http://mylinuxbook.com/5-ways-to-check-if-linux-is-32-bit-or-64-bit/",-1)])]),_:1})]),r("p",null,[t[7]||(t[7]=n("譯者：",-1)),e(a,{href:"https://github.com/crowner"},{default:i(()=>[...t[5]||(t[5]=[n("crowner",-1)])]),_:1}),t[8]||(t[8]=n(" 校對：",-1)),e(a,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...t[6]||(t[6]=[n("Caroline",-1)])]),_:1})]),r("p",null,[t[11]||(t[11]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[9]||(t[9]=[n("LCTT",-1)])]),_:1}),t[12]||(t[12]=n(" 原創翻譯，",-1)),e(a,{href:"http://linux.cn/"},{default:i(()=>[...t[10]||(t[10]=[n("Linux中國",-1)])]),_:1}),t[13]||(t[13]=n(" 榮譽推出",-1))])])}const g=l(d,[["render",m]]);export{C as __pageData,g as default};
